    ("Rails/RedundantReceiverInWithOptions", "gem 'activesupport', '8.1.3.1'\nrequire 'active_support'\nrequire 'active_support/core_ext/object/with_options'\nclass OptionProbe\nattr_reader :events, :state\ndef initialize; @events=[]; @state=:state; end\ndef normalized(value)\ncase value\nwhen ActiveSupport::OptionMerger then :merger\nwhen OptionProbe then :context\nwhen Hash then value.transform_values { |v| normalized(v) }\nwhen Array then value.map { |v| normalized(v) }\nelse value\nend\nend\ndef record(*args, **options); @events << [normalized(args), normalized(options)]; end\ndef value(**options); [:value, options]; end\ndef record=(*args); @events << [:setter, normalized(args)]; end\ndef run\nwith_options(flag: true) { |m| m.puts(1) }\nend\nend\nprobe=OptionProbe.new\nbegin\nprobe.run\nrescue => error\np [:error, error.class.name]\nend\np probe.events\np probe.state\n"),
